def tuple_intersection(test_list1, test_list2):
    """Write a function to find the tuple intersection of elements in the given tuple list irrespective of their order."""

    def _normalize(item):
        try:
            return tuple(sorted(item))
        except TypeError:
            # Elements of mixed/incomparable types: use a deterministic
            # ordering so equivalent tuples normalize identically.
            return tuple(
                sorted(item, key=lambda element: (type(element).__name__, repr(element)))
            )

    normalized_list1 = {_normalize(item) for item in test_list1}
    normalized_list2 = {_normalize(item) for item in test_list2}
    return normalized_list1 & normalized_list2
